<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-pen-to-square" title="Koreksi Kehadiran" subtitle="Ajukan perubahan data presensi" /><div class="card"><h6>Pengajuan Koreksi</h6><div class="grid"><div><label>Tanggal</label><input v-model="form.tanggal" type="date" class="form-control form-control-sm"></div><div><label>Jenis</label><select v-model="form.jenis_koreksi" class="form-select form-select-sm"><option value="Masuk">Masuk</option><option value="Pulang">Pulang</option><option value="Cuti">Cuti</option><option value="Izin">Izin</option></select></div><div><label>Jam</label><input v-model="form.jam_koreksi" type="time" class="form-control form-control-sm"></div><div><label>Jenis Cuti/Izin</label><input v-model="form.jenis_cuti_izin" class="form-control form-control-sm"></div><div class="wide"><label>Alasan</label><textarea v-model="form.alasan" rows="2" class="form-control form-control-sm"></textarea></div><div class="wide"><label>Dokumen</label><input type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" class="form-control form-control-sm" @change="$emit('file-change',$event.target.files[0]||null)"></div><button type="button" class="btn btn-primary wide" :disabled="saving" @click="submit">{{saving?'Menyimpan...':'Ajukan Koreksi'}}</button></div></div><div class="card"><h6>Pengajuan Saya <small>{{ rows.length }}</small></h6><div v-if="!rows.length" class="empty">Belum ada pengajuan.</div><div v-else class="list"><div v-for="x in rows" :key="x.id" class="item"><div class="top"><strong>{{x.jenis_koreksi}}</strong><span class="status" :class="statusClass(x.status)">{{statusLabel(x.status)}}</span></div><small>{{formatDate(x.tanggal)}} · Jam {{formatTime(x.jam_koreksi)}}</small><p>{{x.alasan||'-'}}</p></div></div></div><div v-if="canApprove" class="card"><h6>Menunggu Persetujuan <small>{{approvalRows.length}}</small></h6><div v-if="!approvalRows.length" class="empty">Tidak ada pengajuan menunggu.</div><div v-else class="list"><div v-for="x in approvalRows" :key="x.id" class="item approval"><div class="top"><strong>{{x.pegawai?.nama||'-'}}</strong><span class="status pending">Menunggu</span></div><small>{{x.pegawai?.nip||'-'}} · {{formatDate(x.tanggal)}} · {{x.jenis_koreksi}}</small><p>{{x.alasan||'-'}}</p><div class="actions"><button type="button" @click="approve(x,'approved')">Setujui</button><button type="button" @click="approve(x,'rejected')">Tolak</button></div></div></div></div></div>

</template>
<script setup>import PwaPageHeader from '../../../components/PwaPageHeader.vue';defineProps({rows:{type:Array,default:()=>[]},approvalRows:{type:Array,default:()=>[]},canApprove:Boolean,loading:Boolean,saving:Boolean,form:{type:Object,required:true},formatDate:{type:Function,required:true},formatTime:{type:Function,required:true},statusLabel:{type:Function,required:true},statusClass:{type:Function,required:true},submit:{type:Function,required:true},approve:{type:Function,required:true}});defineEmits(['file-change'])</script>
<style scoped>.attendance-pwa{padding:2px 0 84px}.card{padding:10px;margin-bottom:8px;background:#fff;border:1px solid #e5e7eb;border-radius:15px;box-shadow:0 .2rem .6rem rgba(15,23,42,.05)}h6{margin:0;color:#111827;font-size:15px;font-weight:950}h6 small{color:#64748b;font-size:10px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:9px}.grid .wide{grid-column:1/-1}.grid label{display:block;margin-bottom:3px;color:#475569;font-size:10px;font-weight:900}.grid .form-control,.grid .form-select,.grid .btn{font-size:11.25px}.list{display:flex;flex-direction:column;gap:6px;margin-top:8px}.item{padding:8px;border:1px solid #eef2f7;border-radius:11px}.item.approval{border-left:3px solid #f59e0b}.top{display:flex;justify-content:space-between;gap:6px}.top strong{font-size:12.5px;color:#111827}.item small{display:block;margin-top:3px;color:#64748b;font-size:9.38px}.item p{margin:6px 0 0;color:#334155;font-size:10.62px;line-height:1.3}.status{padding:3px 5px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:8.75px;font-weight:900}.status.approved{background:#dcfce7;color:#166534}.status.pending{background:#fef3c7;color:#92400e}.status.rejected{background:#fee2e2;color:#991b1b}.actions{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:7px}.actions button{height:28px;border:0;border-radius:8px;background:#dcfce7;color:#166534;font-size:10.62px;font-weight:900}.actions button:last-child{background:#fee2e2;color:#991b1b}.empty{text-align:center;padding:18px;color:#64748b;font-size:11.25px}@media(max-width:410px){.grid{grid-template-columns:1fr}.grid .wide{grid-column:1}}</style>